const current = JSON.parse(r.output);
const original = load("inventory_original_files");
const protectedPaths = ['README.md', 'verify.py', 'test_public.py', 'project/compat.py'];
for (const name of protectedPaths) {
  if (current.files[name].sha256 !== original[name].sha256) throw new Error(`Protected file changed: ${name}`);
